"""No secret-bearing file may be tracked by git.

The repository gitignores its generated environments (`.env`, `.env.staging`,
`.env.check`) but `.env.check` was nevertheless committed — added before the
ignore rule existed, and never removed. Its own first line reads:

    # Generated by scripts/make_check_env.py — DO NOT COMMIT (mode 0600)

and it carried real, non-empty values for `SECRET_KEY`, `JWT_SECRET`,
`POSTGRES_PASSWORD`, `GRAFANA_ADMIN_PASSWORD`, `CONDUCTOR_WEBHOOK_SECRET`,
`REALTIME_GATEWAY_INGEST_SECRET` and the owner account passwords, which
`scripts/make_check_env.py` generates with `secrets.token_hex`. The blank
provider keys in the same file are what made it look harmless.

`.gitignore` does not untrack a file that is already tracked, so the rule in
`.gitignore` gave a false sense of protection and every clone received the
secrets. These tests fail if that happens again, or if a new secret file is
committed alongside the existing rules.
"""

from __future__ import annotations

import re
import subprocess
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parents[2]

#: Secret *names* whose values must never be committed with a real value.
SECRET_KEY_PATTERN = re.compile(
    r"(SECRET|PASSWORD|API_KEY|AUTH_TOKEN|TOKEN|PRIVATE_KEY|_KEY)$", re.IGNORECASE
)

#: A value that is obviously a placeholder rather than a live credential.
PLACEHOLDER_VALUES = frozenset(
    {
        "",
        "changeme",
        "change-me",
        "replace-me",
        "your-key-here",
        "example",
        "test",
        "dummy",
    }
)


def _tracked_files() -> list[str]:
    out = subprocess.run(
        ["git", "ls-files"],
        cwd=REPO_ROOT,
        capture_output=True,
        text=True,
        check=True,
    )
    return [line for line in out.stdout.splitlines() if line.strip()]


def test_no_env_file_is_tracked():
    """`.env` and its variants are generated locally and must stay untracked."""
    tracked = _tracked_files()
    offenders = [
        path
        for path in tracked
        if re.fullmatch(r"(^|.*/)\.env(\.[A-Za-z0-9_-]+)?", path)
        and not path.endswith(".example")
    ]
    assert offenders == [], (
        "generated environment files are tracked; run "
        f"`git rm --cached <path>`: {offenders}"
    )


def _env_shaped(path: str) -> bool:
    """True for files that carry `NAME=value` environment data.

    Deliberately narrow. A repository-wide grep for `SECRET=` also matches
    docstrings, SQLAlchemy `sa.Column(...)` calls and test kwargs that are not
    credentials at all, which would make this guard either uselessly noisy or
    silently weakened until it caught nothing. Only environment payloads are
    inspected here.
    """
    name = Path(path).name
    if name.startswith(".env") or name.endswith((".env", ".ini", ".cfg")):
        return True
    return path.endswith(".env.example")


def test_tracked_env_files_carry_no_live_secret():
    """An env-shaped file may only carry blank or obvious placeholder values."""
    offenders: list[str] = []
    for path in _tracked_files():
        if not _env_shaped(path) or path.endswith(".example"):
            continue
        full = REPO_ROOT / path
        try:
            text = full.read_text(encoding="utf-8", errors="strict")
        except (OSError, UnicodeDecodeError):
            continue
        for lineno, line in enumerate(text.splitlines(), start=1):
            stripped = line.strip()
            if not stripped or stripped.startswith("#") or "=" not in stripped:
                continue
            name, _, value = stripped.partition("=")
            name = name.strip()
            value = value.strip().strip('"').strip("'")
            if not SECRET_KEY_PATTERN.search(name):
                continue
            if value.lower() in PLACEHOLDER_VALUES or value.startswith("${"):
                continue
            offenders.append(f"{path}:{lineno}: {name}")
    assert offenders == [], (
        "tracked environment files carry live-looking secrets; untrack them "
        f"with `git rm --cached` and rotate the values: {offenders}"
    )


def test_the_generated_check_env_is_ignored_not_tracked():
    """`.env.check` is produced by `scripts/make_check_env.py` at run time."""
    result = subprocess.run(
        ["git", "check-ignore", "-q", ".env.check"], cwd=REPO_ROOT
    )
    assert result.returncode == 0, ".env.check must be gitignored"
    assert ".env.check" not in _tracked_files()
